@triton.jit
def mba_dual_dispatch_v8_kernel(
    a_ptr,
    b_ptr,
    bias_ptr,
    c_ptr,
    M,
    N,
    K,
    stride_am,
    stride_ak,
    stride_bk,
    stride_bn,
    stride_bias,
    stride_cm,
    stride_cn,
    BLOCK_SIZE_M: tl.constexpr,
    BLOCK_SIZE_N: tl.constexpr,
    BLOCK_SIZE_K: tl.constexpr,
):
    """Two N-adjacent tiles per program so the A panel is fetched once."""
    pid = tl.program_id(0)
    num_pid_m = tl.cdiv(M, BLOCK_SIZE_M)
    pid_m = pid % num_pid_m
    pid_n = pid // num_pid_m

    offs_am = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_bn = pid_n * (2 * BLOCK_SIZE_N) + tl.arange(0, BLOCK_SIZE_N)
    offs_k = tl.arange(0, BLOCK_SIZE_K)
    a_ptrs = a_ptr + (offs_am[:, None] * stride_am + offs_k[None, :] * stride_ak)
    b0_ptrs = b_ptr + (offs_k[:, None] * stride_bk + offs_bn[None, :] * stride_bn)
    b1_ptrs = b0_ptrs + BLOCK_SIZE_N * stride_bn

    acc0 = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)
    acc1 = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)
    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K)):
        a = tl.load(a_ptrs)
        b0 = tl.load(b0_ptrs)
        b1 = tl.load(b1_ptrs)
        acc0 = tl.dot(a, b0, acc0, allow_tf32=False)
        acc1 = tl.dot(a, b1, acc1, allow_tf32=False)
        a_ptrs += BLOCK_SIZE_K * stride_ak
        b0_ptrs += BLOCK_SIZE_K * stride_bk
        b1_ptrs += BLOCK_SIZE_K * stride_bk

    offs_cm = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_cn = pid_n * (2 * BLOCK_SIZE_N) + tl.arange(0, BLOCK_SIZE_N)
    base = c_ptr + stride_cm * offs_cm[:, None]
    bias0 = tl.load(bias_ptr + offs_cn * stride_bias)
    bias1 = tl.load(bias_ptr + (offs_cn + BLOCK_SIZE_N) * stride_bias)
    v0 = acc0 + bias0[None, :]
    v1 = acc1 + bias1[None, :]
    v0 = tl.maximum(v0, v0 * 0.0)
    v1 = tl.maximum(v1, v1 * 0.0)
    tl.store(base + stride_cn * offs_cn[None, :], v0.to(bias0.dtype))
    tl.store(base + stride_cn * (offs_cn + BLOCK_SIZE_N)[None, :], v1.to(bias1.dtype))


# ---------------------------------------------------------------------------
# v9 (2026-10-14): FP32 dual-N-tile path.
#
# Diagnosis for the previous best: every regular fp32 case is slower than
# PyTorch (1024: 0.717x, 2048: 0.792x, 4096: 0.979x) even though fp32 is the
# only dtype whose large cases are not already at the PyTorch level. The v8
# A-reuse dual tile path is gated on float16/bfloat16 only, so fp32 falls
# through to v6, which keeps GROUP=4 / GROUP=0 and a plain single-N-tile
# kernel. The AIC profile of the fp32 1024 case (aic_mte2 0.55, aic_mac 0.64,
# cube 71.4%) shows the data pipeline and the MAC issue slots are both only
# partially active -- the cube stalls between K iterations rather than being
# saturated, which is what an under-fed K loop with one N tile looks like.
#
# Change: extend the v8 dual-N-tile kernel (one A panel fetch per K step,
# two B tiles, two accumulators) to the fp32 regular square cases 1024/2048/
# 4096, with the fp32 K block kept at BK=128 (the entry size that the
# accepted fp32 configuration in this operator's history uses; fp32 is 4
# bytes so a BK=256 panel is 2x the bytes of the fp16 BK=256 panel). The
# rule is expressed as a half-K bound: BK = 128 when the k-block byte size
# exceeds the fp16-equivalent 2*256 = 512 bytes, i.e. BK = min(256, 512 //
# element_size). For fp16/bf16 this yields 256, exactly the current accepted
# value, so those cases are bit-identical to the current path and are routed
# to the unchanged v8 dispatcher.
# ---------------------------------------------------------------------------

_v6_dispatch = run


